'use client';
import {useEffect,useState} from 'react';
import Link from 'next/link';
import {api,API_BASE,download} from '@/services/api';
import {describeMode} from '@/services/protocol.mjs';
import {navigation} from './Sidebar';
import ResultView,{Notice,Empty} from './ResultView';
import DocumentUploader from './DocumentUploader';
import ChatBox from './ChatBox';

type PageProps={page:string};
function useResource(path:string){const[data,setData]=useState<any>(null);const[error,setError]=useState('');const[busy,setBusy]=useState(true);const[nonce,setNonce]=useState(0);useEffect(()=>{let active=true;setBusy(true);setError('');api(path).then(d=>{if(active)setData(d);}).catch(e=>{if(active)setError(e.message);}).finally(()=>{if(active)setBusy(false);});return()=>{active=false;};},[path,nonce]);return{data,error,busy,reload:()=>setNonce(n=>n+1)};}
function Loading(){return <div className="loading-state" role="status"><span className="spinner"/>Loading workspace data…</div>;}
function ErrorBox({error,retry}:{error:string,retry?:()=>void}){return <Notice type="error"><strong>Request could not be completed.</strong><p>{error}</p>{retry&&<button className="button small secondary" onClick={retry}>Retry</button>} <Link href="/settings">Check settings</Link></Notice>;}
function PageHeader({page,description,action}:{page:string,description:string,action?:React.ReactNode}){return <div className="page-header"><div><span className="eyebrow">IP-SAKTI / INTELLIGENCE</span><h1>{navigation.find(n=>n[0]===page)?.[1]||page}</h1><p>{description}</p></div>{action}</div>;}
function statusLabel(value:any){const state=String(value?.status??value??'unavailable').toLowerCase();if(['ready','configured','initialized','indexed','available','live','local'].includes(state))return'Ready';if(state==='mock')return'Ready · Synthetic';if(['unconfigured','not_configured','authorization_required','empty','not_indexed','degraded'].includes(state))return'Needs configuration';if(state==='configured_not_verified')return'Configured ? not verified';return'Unavailable';}
function statusTone(value:any){const label=statusLabel(value);return label.startsWith('Ready')?'ready':label==='Unavailable'?'unavailable':'attention';}
function StatusGrid({providers}:{providers:any}) {return <div className="provider-grid">{Object.entries(providers||{}).map(([key,value])=><div key={key}><span>{key.replaceAll('_',' ')}</span><strong className={`service-state ${statusTone(value)}`}><i/>{statusLabel(value)}</strong></div>)}</div>;}
function formatFileSize(bytes:number){if(!Number.isFinite(bytes))return'Size unavailable';if(bytes<1024)return`${bytes} B`;if(bytes<1024*1024)return`${(bytes/1024).toFixed(1)} KB`;return`${(bytes/(1024*1024)).toFixed(1)} MB`;}
function formatLocalTime(value:string){if(!value)return'Date unavailable';const canonical=/(?:Z|[+-]\d\d:\d\d)$/i.test(value)?value:`${value}Z`;const date=new Date(canonical);if(Number.isNaN(date.getTime()))return'Date unavailable';try{return new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(date);}catch{return date.toLocaleString();}}
function reportMetrics(report:any){const assessment=report.assessment||{};const trust=assessment.trust||{};const citations=assessment.citations||assessment.results?.[assessment.routing?.primary]?.citations||[];return{status:String(assessment.status||report.status||'saved').replaceAll('_',' '),trust:trust.trust_score,evidence:trust.evidence_score,sources:Array.isArray(citations)?citations.length:0};}
function EvidenceMap({providers,busy}:{providers:any,busy:boolean}){const state=(keys:string[])=>{if(busy)return 'CHECKING';const v=keys.map(k=>providers?.[k]).find(Boolean);return v?String(v).replaceAll('_',' ').toUpperCase():'NOT CONFIGURED';};const paths:[string,string[]][]=[['PATENT',['prior_art','epo','patent']],['PRIOR ART',['prior_art','epo']],['TK',['traditional_knowledge','tk']],['REGULATION',['regulation']],['COMPLIANCE',['compliance']]];return <section className="evidence-map panel" aria-labelledby="evidence-map-title"><div className="section-title"><div><span className="eyebrow">LIVE RESEARCH SCOPE</span><h2 id="evidence-map-title">Evidence Intelligence Map</h2></div><small>Provider status only — no search is run here.</small></div><div className="map-canvas"><div className="map-lines" aria-hidden="true"><i/><i/><i/><i/><i/></div><div className="idea-node"><span>AYUSH</span><strong>IDEA</strong><small>start an inquiry</small></div>{paths.map(([label,keys],index)=><div className={`map-node map-node-${index+1}`} key={label}><span>{label}</span><strong className={state(keys)==='NOT CONFIGURED'?'map-off':''}>{state(keys)}</strong></div>)}</div><p className="fine-print">Connected paths identify available investigation surfaces. A provider state is not evidence, verification, clearance, or a legal conclusion.</p></section>}
function Dashboard(){const{data,error,busy,reload}=useResource('/status');const reports=useResource('/reports');const[q,setQ]=useState('');const dashboardError = error || reports.error;return <><PageHeader page="dashboard" description="Trace an AYUSH idea through the available evidence surfaces before drawing a conclusion." action={<Link className="button primary" href="/ask">Open investigation ↗</Link>}/>{dashboardError&&<ErrorBox error={dashboardError} retry={error ? reload : reports.reload}/>}<div className="dashboard-banner"><div><span className="eyebrow">RESEARCH COMMAND</span><h2>What would you like<br/>to investigate?</h2><p>Begin with a precise question. IP-SAKTI keeps sources, limitations and review gaps in the same case file.</p><form className="quick-search" onSubmit={e=>{e.preventDefault();window.location.href=`/ask?question=${encodeURIComponent(q)}`;}}><input aria-label="Start a research question" placeholder="e.g., a turmeric wound-care formulation" value={q} required onChange={e=>setQ(e.target.value)}/><button aria-label="Ask IP-SAKTI" type="submit">↗</button></form></div><div className="principle-card"><span className="large-mark">IS</span><strong>Evidence before assertion</strong><p>Screening is traceable; conclusions remain reviewable.</p><span className="badge light">Human review essential</span></div></div><EvidenceMap providers={data?.providers} busy={busy}/>
 <div className="section-title"><h2>Investigation paths</h2><span className="muted">Select a research surface</span></div><div className="task-grid">{[['patentability','IP','Patentability Check','Screen the invention and expose readiness gaps.'],['prior-art','PA','Prior-Art Intelligence','Inspect retrieved patent records and overlap.'],['tk-risk','TK','Traditional Knowledge Risk','Separate screening from clearance evidence.'],['regulation-compare','RG','Global Regulation Compare','Compare source-bound jurisdictional requirements.']].map(([href,icon,title,desc])=><Link className="task-card" key={href} href={`/${href}`}><span className="task-icon">{icon}</span><span className="task-arrow">↗</span><h3>{title}</h3><p>{desc}</p></Link>)}</div>
 <div className="two-columns dashboard-bottom"><section className="panel"><div className="section-title"><h2>Case file counts</h2><span className="step-label">WORKSPACE INDEX</span></div><div className="metric-grid">{[['Source documents',data?.documents,'stored in workspace'],['Saved reports',data?.reports,'traceable snapshots'],['Jurisdictions',4,'India · USA · EU · UK'],['Languages',3,'English · Hindi · Marathi']].map(([label,value,sub])=><div className="metric-card" key={String(label)}><span>{label}</span><strong>{value??'—'}</strong><small>{sub}</small></div>)}</div></section><section className="panel"><div className="section-title"><h2>Recent assessments</h2><Link href="/reports">View all</Link></div>{reports.error && !error ? null : reports.data?.reports?.length?<div className="report-list">{reports.data.reports.slice(0,4).map((r:any)=><Link href="/reports" key={r.id}><span className="file-icon">R</span><div><strong>{r.title}</strong><small>{new Date(r.created_at).toLocaleString()} · {describeMode(r.mode)}</small></div><span>↗</span></Link>)}</div>:<Empty title="No assessments in this case file">Complete a screening, then save its report for later review.</Empty>}</section></div></>;}
function BrightDashboard(){
 const{data,error,busy,reload}=useResource('/status');
 const reports=useResource('/reports');
 const[q,setQ]=useState('');
 const providers=Object.entries(data?.providers||{});
 const connected=providers.filter(([,value])=>!['unconfigured','unavailable','disabled'].includes(String(value))).length;
 const reportItems=reports.data?.reports||[];
 const quick=[['ask','◌','Ask IP-SAKTI'],['patentability','▤','Patentability Check'],['prior-art','⌕','Prior-Art Search'],['tk-risk','✦','TK Risk']];
 const dashboardError = error || reports.error;
 return <>
  <section className="dashboard-welcome" aria-labelledby="welcome-title">
   <div className="welcome-copy"><span className="eyebrow">WELCOME TO</span><h1 id="welcome-title">IP-SAKTI Intelligence</h1><p>Evidence-grounded IP &amp; regulatory intelligence for AYUSH.</p><div className="welcome-saying">Traditional wisdom<br/>Informed decisions<br/>Greater impact</div></div>
   <div className="botanical-visual" aria-label="Science Meets Tradition botanical illustration"><span className="leaf leaf-one"/><span className="leaf leaf-two"/><span className="leaf leaf-three"/><span className="mortar">⌁</span><i>Science<br/>Meets<br/><b>Tradition</b></i></div>
   <form className="investigate-box" onSubmit={e=>{e.preventDefault();if(q.trim())window.location.href=`/ask?question=${encodeURIComponent(q.trim())}`;}}><div className="investigate-input"><span aria-hidden="true">⌕</span><input aria-label="What would you like to investigate?" placeholder="What would you like to investigate?" value={q} onChange={e=>setQ(e.target.value)} required/><button className="button primary" type="submit">Investigate <b>→</b></button></div><small>Ask a precise question. IP-SAKTI searches across configured patents, traditional knowledge, regulations and more.</small><div className="quick-actions"><strong>Quick actions:</strong>{quick.map(([href,icon,label])=><Link href={`/${href}`} key={href}><span>{icon}</span>{label}</Link>)}</div></form>
  </section>
  {dashboardError&&<ErrorBox error={dashboardError} retry={error ? reload : reports.reload} />} 
  <section className="summary-grid" aria-label="Workspace summary">
   <Link href="/knowledge-library" className="summary-card knowledge"><span className="summary-icon">▱</span><div><small>Knowledge Base</small><strong>{busy?'Checking sources':'Source library'}</strong><p>Documents, publications and traditional knowledge records.</p></div><b>→</b></Link>
   <Link href="/ask" className="summary-card trust"><span className="summary-icon">⌁</span><div><small>Trust Engine</small><strong>Evidence-backed</strong><p>Traceable sources, limitations and review cues.</p></div><b>→</b></Link>
   <Link href="/settings" className="summary-card providers"><span className="summary-icon">▤</span><div><small>Providers</small><strong>{busy?'Checking status':providers.length?`${connected} ready / ${providers.length}`:'Not configured'}</strong><p>Only configured sources are represented as available.</p></div><b>→</b></Link>
   <Link href="/reports" className="summary-card reports"><span className="summary-icon">▥</span><div><small>Reports</small><strong>Generate &amp; export</strong><p>Keep assessments together with their source context.</p></div><b>→</b></Link>
  </section>
  <section className="workflow-panel" aria-labelledby="workflow-title"><div className="section-title"><div><span className="eyebrow">EVIDENCE INTELLIGENCE</span><h2 id="workflow-title">From your question to a traceable answer.</h2></div><span className="workflow-note">How it works ⓘ</span></div><div className="workflow-steps">{[['01','Understand','Analyse your query, formulation and context.'],['02','Search','Across configured patents, TK and regulations.'],['03','Analyse','Identify relevant evidence, risks and gaps.'],['04','Deliver','Clear, traceable insights with source links.']].map(([number,title,text],index)=><div className="workflow-step" key={number}><span>{number}</span><div><strong>{title}</strong><small>{text}</small></div>{index<3&&<b aria-hidden="true">→</b>}</div>)}</div></section>
  <div className="dashboard-content-grid"><section className="panel recent-panel"><div className="section-title"><div><span className="eyebrow">RECENT ASSESSMENTS</span><h2>Your recent investigations</h2></div><Link href="/reports">View all →</Link></div>{reports.busy?<Loading/>:reports.error && !error ? null : !reportItems.length?<Empty title="No assessments yet">Start an investigation and save the result when you are ready to retain its evidence and limitations.</Empty>:<div className="recent-list">{reportItems.slice(0,5).map((report:any)=><Link href="/reports" key={report.id}><span className="recent-type">{report.kind?.replaceAll('_',' ')||'Assessment'}</span><strong>{report.title}</strong><small>{report.mode?describeMode(report.mode):'Stored result'} · {report.created_at?new Date(report.created_at).toLocaleDateString():'Date unavailable'}</small><b>View →</b></Link>)}</div>}</section><aside className="dashboard-side"><section className="panel provider-status-card"><div className="section-title"><h2>Provider Status</h2><Link href="/settings">Manage</Link></div>{busy?<Loading/>:providers.length?<StatusGrid providers={data.providers}/>:<p className="fine-print">No provider state has been returned. Configure a provider before relying on a search.</p>}</section><section className="help-card"><span>◌</span><div><h3>Need help?</h3><p>Ask a question, explore a workflow, or understand a source limitation.</p><Link className="button secondary small" href="/ask">Ask IP-SAKTI <b>→</b></Link></div></section></aside></div>
 </>;
}
function RefinedDashboard(){
 const{data,error,busy,reload}=useResource('/status');const reports=useResource('/reports');const[q,setQ]=useState('');
 const providers=Object.entries(data?.providers||{});const connected=providers.filter(([,value])=>!['unconfigured','unavailable','disabled'].includes(String(value))).length;
 const actions=[['ask','◌','Ask IP-SAKTI','Ask an evidence-grounded AYUSH question.'],['patentability','▤','Patentability Check','Screen an invention for readiness gaps.'],['prior-art','⌕','Prior-Art Search','Search configured patent records.'],['tk-risk','✦','TK Risk','Review traditional knowledge overlap.']];
 const reportItems=reports.data?.reports||[];
 const dashboardError = Array.from(new Set([error, reports.error].filter(Boolean))).join(' • ') || '';
 const dashboardRetry = error ? reload : reports.reload;
 return <><section className="dashboard-welcome compact-welcome" aria-labelledby="welcome-title"><div className="welcome-copy"><span className="eyebrow">WELCOME TO</span><h1 id="welcome-title">IP-SAKTI Intelligence</h1><p>Evidence-grounded IP &amp; regulatory intelligence for AYUSH.</p><div className="welcome-saying">Traditional wisdom<br/>Informed decisions<br/>Greater impact</div></div><div className="botanical-visual" aria-label="Science Meets Tradition botanical illustration"><span className="leaf leaf-one"/><span className="leaf leaf-two"/><span className="leaf leaf-three"/><span className="mortar">⌁</span><i>Science<br/>Meets<br/><b>Tradition</b></i></div><form className="investigate-box" onSubmit={e=>{e.preventDefault();if(q.trim())window.location.href=`/ask?question=${encodeURIComponent(q.trim())}`;}}><div className="investigate-input"><span aria-hidden="true">⌕</span><input aria-label="What would you like to investigate?" placeholder="What would you like to investigate?" value={q} onChange={e=>setQ(e.target.value)} required/><button className="button primary" type="submit">Investigate <b>→</b></button></div><small>Start with a precise question. Searches run only after you choose Investigate.</small></form></section>{dashboardError&&<ErrorBox error={dashboardError} retry={dashboardRetry} />}<section className="summary-grid compact-summary" aria-label="Workspace summary"><Link href="/knowledge-library" className="summary-card knowledge"><span className="summary-icon">▱</span><div><small>Knowledge Base</small><strong>{busy?'Checking sources':'Source library'}</strong><p>Documents, publications and TK records.</p></div><b>→</b></Link><Link href="/ask" className="summary-card trust"><span className="summary-icon">⌁</span><div><small>Trust Engine</small><strong>Evidence-backed</strong><p>Sources, scope and limitations together.</p></div><b>→</b></Link><Link href="/settings" className="summary-card providers"><span className="summary-icon">▤</span><div><small>Providers</small><strong>{busy?'Checking status':providers.length?`${connected} ready / ${providers.length}`:'Not configured'}</strong><p>Only configured sources are shown.</p></div><b>→</b></Link><Link href="/reports" className="summary-card reports"><span className="summary-icon">▥</span><div><small>Reports</small><strong>Generate &amp; export</strong><p>Save assessments with their context.</p></div><b>→</b></Link></section><section className="action-card-grid" aria-label="Start an investigation">{actions.map(([href,icon,title,description])=><Link href={`/${href}`} key={href} className="action-card"><span>{icon}</span><div><strong>{title}</strong><small>{description}</small></div><b>→</b></Link>)}</section><div className="dashboard-content-grid refined-dashboard-grid"><section className="panel recent-panel"><div className="section-title"><div><span className="eyebrow">RECENT ASSESSMENTS</span><h2>Your recent investigations</h2></div><Link href="/reports">View all →</Link></div>{reports.busy?<Loading/>:reports.error && !error ? null : !reportItems.length?<Empty title="No assessments yet">Start with a question or a screening tool, then save an assessment to retain its evidence and limitations.<br/><Link className="button primary small empty-cta" href="/ask">Ask IP-SAKTI</Link></Empty>:<div className="recent-list">{reportItems.slice(0,5).map((report:any)=><Link href="/reports" key={report.id}><span className="recent-type">{report.kind?.replaceAll('_',' ')||'Assessment'}</span><strong>{report.title}</strong><small>{report.mode?describeMode(report.mode):'Stored result'} · {report.created_at?new Date(report.created_at).toLocaleDateString():'Date unavailable'}</small><b>View →</b></Link>)}</div>}</section><aside className="dashboard-side"><section className="panel provider-status-card"><div className="section-title"><h2>Provider Status</h2><Link href="/settings">Manage</Link></div>{busy?<Loading/>:providers.length?<StatusGrid providers={data.providers}/>:<p className="fine-print">No provider state has been returned. Configure a provider before relying on a search.</p>}</section><section className="help-card"><span>◌</span><div><h3>Need help?</h3><p>Explore a workflow or understand a source limitation.</p><Link className="button secondary small" href="/ask">Ask IP-SAKTI <b>→</b></Link></div></section></aside></div><section className="workflow-panel compact-workflow" aria-labelledby="workflow-title"><div className="section-title"><div><span className="eyebrow">EVIDENCE INTELLIGENCE</span><h2 id="workflow-title">From your question to a traceable answer.</h2></div><span className="workflow-note">How it works ⓘ</span></div><div className="workflow-steps">{[['01','Understand','Analyse your query and context.'],['02','Search','Configured patents, TK and regulations.'],['03','Analyse','Identify evidence, risks and gaps.'],['04','Deliver','Traceable insights with sources.']].map(([number,title,text],index)=><div className="workflow-step" key={number}><span>{number}</span><div><strong>{title}</strong><small>{text}</small></div>{index<3&&<b aria-hidden="true">→</b>}</div>)}</div></section></>;
}
function AutoTextarea({value,onChange,placeholder,required=false,helper,rows=3}:{value:string,onChange:(value:string)=>void;placeholder:string;required?:boolean;helper:string;rows?:number}){return <><textarea rows={rows} value={value} placeholder={placeholder} required={required} onChange={e=>onChange(e.target.value)} onInput={e=>{const area=e.currentTarget;area.style.height='auto';area.style.height=`${area.scrollHeight}px`;}}/><small className="field-helper">{helper}</small></>;}
function SourceSafety({page}:{page:string}){const message=page==='prior-art'?'A real search requires a configured patent provider. An empty or limited search cannot establish novelty.':page==='tk-risk'?'This assessment searches only the configured corpus. NO AUTHORIZED TK SEARCH → NO FINAL TK CLEARANCE.':'Every screening result should be read with its sources, coverage and limitations.';return <details className="source-safety"><summary><span>⌁</span> Evidence &amp; source safety <b>⌄</b></summary><div><h3>Every conclusion needs a source.</h3><p>{message}</p><p>Scores describe completeness, overlap or grounding; they do not measure legal correctness.</p><Link href="/knowledge-library">Inspect your source library →</Link></div></details>}
function RefinedScreenForm({page}:PageProps){const cfg=FORM_CONFIG[page];const[values,setValues]=useState<Record<string,string>>({question:'',title:'',description:'',ingredients:'',process:'',claimed_innovation:'',technical_advantage:'',therapeutic_use:'',language:'en',intent:'',jurisdiction:'IN',product_category:'herbal_product',document_text:'',as_of:'',document_id:''});const[countries,setCountries]=useState(['IN','US','EU','UK']);const[runPrior,setRunPrior]=useState(false);const[result,setResult]=useState<any>(null);const[lastInput,setLastInput]=useState<any>(null);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[saving,setSaving]=useState(false);const[saved,setSaved]=useState('');const[voiceMessage,setVoiceMessage]=useState('');const set=(key:string,value:string)=>setValues(v=>({...v,[key]:value}));
 useEffect(()=>{const savedLanguage=localStorage.getItem('ip-sakti-language')||'en';set('language',savedLanguage);if(page==='ask')set('question',new URLSearchParams(window.location.search).get('question')||'');},[page]);const invention=['patentability','prior-art','tk-risk'].includes(page);const compliance=['document-checker','compliance-journey'].includes(page);const makeInput=()=>{if(page==='ask')return{question:values.question,language:values.language,...(values.intent?{intent:values.intent}:{})};if(page==='regulation-compare')return{jurisdictions:countries,product_category:values.product_category,...(values.as_of?{as_of:values.as_of}:{})};if(compliance)return{jurisdiction:values.jurisdiction,product_category:values.product_category,document_text:values.document_text,...(values.document_id?{document_id:values.document_id}:{}),...(values.as_of?{as_of:values.as_of}:{})};const common={title:values.title,description:values.description,ingredients:values.ingredients.split(',').map(s=>s.trim()).filter(Boolean),process:values.process};if(page==='tk-risk')return{...common,therapeutic_use:values.therapeutic_use};return{...common,claimed_innovation:values.claimed_innovation,technical_advantage:values.technical_advantage,...(page==='patentability'?{run_prior_art_search:runPrior}:{limit:10})};};
 const input=(key:string,label:string,helper:string,placeholder='',required=false)=><label className="form-field" key={key}><span>{label}{required&&<b className="required"> *</b>}</span><input value={values[key]} placeholder={placeholder} required={required} onChange={e=>set(key,e.target.value)}/><small className="field-helper">{helper}</small></label>;const textArea=(key:string,label:string,helper:string,placeholder='',required=false)=><label className="form-field" key={key}><span>{label}{required&&<b className="required"> *</b>}</span><AutoTextarea value={values[key]} onChange={value=>set(key,value)} placeholder={placeholder} required={required} helper={helper}/></label>;
 const submit=async(e:React.FormEvent)=>{e.preventDefault();if(busy)return;setError('');setSaved('');setBusy(true);setResult(null);const payload=makeInput();try{const response=await api(cfg.endpoint,payload);setResult(response);setLastInput(payload);}catch(err){setError((err as Error).message);}finally{setBusy(false);}};const inventionSteps=<div className="screening-stepper"><details open><summary><span>1</span><strong>Basic information</strong><small>Describe what you are screening.</small></summary><div className="step-body"><div className="field-group">{input('title','Invention or product title','Use a clear working name for this screening.','Name your invention',page!=='tk-risk')}{input('ingredients','Ingredients','Separate each ingredient with a comma.','e.g., turmeric, neem, aloe vera')}</div>{textArea('description','Description','Describe the formulation, use and technical details that matter.','Describe the formulation, use and technical details.',true)}</div></details><details><summary><span>2</span><strong>Ingredients / invention details</strong><small>Record the core elements of your claim.</small></summary><div className="step-body">{page==='tk-risk'?textArea('therapeutic_use','Claimed therapeutic use','Describe the claimed use; this does not verify efficacy.','Describe the claimed use.'):textArea('claimed_innovation','Claimed innovation','Explain what change or improvement is proposed.','What change are you proposing?')}</div></details><details><summary><span>3</span><strong>Process / advanced details</strong><small>Add preparation and supporting evidence.</small></summary><div className="step-body"><div className="field-group">{textArea('process','Preparation process','Describe the actual preparation steps.','Describe the actual preparation steps.')}{page!=='tk-risk'&&textArea('technical_advantage','Technical advantage','Add measurements or evidence supporting the proposed advantage.','Describe measurements or available evidence.')}</div></div></details><details><summary><span>4</span><strong>Review and submit</strong><small>Confirm the scope before running the screen.</small></summary><div className="step-body review-step">{page==='patentability'&&<label className="checkbox-label"><input type="checkbox" checked={runPrior} onChange={e=>setRunPrior(e.target.checked)}/>Include configured prior-art search</label>}<p className="fine-print">This is a screening workflow. Review sources and limitations before relying on any result.</p><div className="form-actions"><small>Submission starts the configured screening. Nothing runs while you complete these steps.</small><button className="button primary" disabled={busy} type="submit">{busy?<><span className="spinner"/>Processing…</>:page==='patentability'?'Check Patentability':page==='prior-art'?'Search Prior Art':'Assess TK Risk'}</button></div></div></details></div>;
 const standardForm=<>{page==='ask'&&<><ChatBox value={values.question} onChange={v=>set('question',v)} language={values.language}/><div className="form-row"><label className="form-field"><span>Response language</span><select value={values.language} onChange={e=>set('language',e.target.value)}><option value="en">English</option><option value="hi">हिन्दी</option><option value="mr">मराठी</option></select><small className="field-helper">Choose the language used in the response.</small></label><label className="form-field"><span>Route</span><select value={values.intent} onChange={e=>set('intent',e.target.value)}><option value="">Detect intent</option><option value="ask">Grounded question answering</option><option value="patent">Patent agent</option><option value="prior_art">Prior-art agent</option><option value="traditional_knowledge">Traditional knowledge agent</option><option value="international">International regulation agent</option><option value="ayush">AYUSH agent</option><option value="compliance">Compliance agent</option></select><small className="field-helper">Leave as Detect intent for automatic routing.</small></label></div></>}{page==='regulation-compare'&&<fieldset><legend>Jurisdictions</legend><small className="field-helper">Select the jurisdictions you want to compare. Missing evidence is shown as missing, not as no requirement.</small><div className="country-options">{[['IN','India'],['US','USA'],['EU','European Union'],['UK','United Kingdom']].map(([code,label])=><label className={countries.includes(code)?'selected':''} key={code}><input type="checkbox" checked={countries.includes(code)} onChange={e=>setCountries(c=>e.target.checked?[...c,code]:c.filter(v=>v!==code))}/><span><strong>{code}</strong>{label}</span></label>)}</div></fieldset>}{(page==='regulation-compare'||compliance)&&<>{compliance&&<label className="form-field"><span>Jurisdiction</span><select value={values.jurisdiction} onChange={e=>set('jurisdiction',e.target.value)}>{[['IN','India'],['US','USA'],['EU','European Union'],['UK','United Kingdom']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select><small className="field-helper">Choose the jurisdiction supplied by the source corpus.</small></label>}{input('product_category','Product category','Use a category that matches the configured source corpus.','e.g., herbal product',true)}<label className="form-field"><span>Assessment date</span><input type="date" value={values.as_of} onChange={e=>set('as_of',e.target.value)}/><small className="field-helper">Leave blank to use today; only stored versions for the selected date are used.</small></label></>}{compliance&&<>{textArea('document_text','Document text','Paste explicit labelled fields such as product name, ingredients and manufacturer.','Product name: …\nIngredients: …\nManufacturer: …')}{input('document_id','Stored document ID (optional)','Copy a document ID from Knowledge Library if you want to reference it.','Copy an ID from Knowledge Library')}<Link href="/knowledge-library">Upload or inspect a document →</Link></>}<div className="form-actions"><small>Review source scope and limitations before relying on a result.</small><button className="button primary" disabled={busy||(page==='regulation-compare'&&!countries.length)} type="submit">{busy?<><span className="spinner"/>Processing…</>:cfg.button}</button></div></>;
 return <><PageHeader page={page} description={cfg.title}/><section id="screening-form" className="panel refined-form-panel"><form onSubmit={submit}>{invention?inventionSteps:standardForm}</form>{error&&<ErrorBox error={error}/>}</section><SourceSafety page={page}/>{busy?<Loading/>:<section className="panel result-panel"><div className="result-actions">{result&&<><button className="button secondary small" disabled={saving} onClick={async()=>{setSaving(true);setSaved('');try{await api('/reports',{title:`${navigation.find(n=>n[0]===page)?.[1]} report`,kind:cfg.kind,...(result.assessment_id?{assessment_id:result.assessment_id}:{input:lastInput})});setSaved('Report saved. Open Reports to export it.');}catch(e){setSaved((e as Error).message);}finally{setSaving(false);}}}>{saving?'Saving report…':'Save assessment report'}</button>{page==='ask'&&<button className="button ghost small" onClick={async()=>{try{const r=await api('/voice/synthesize',{text:result.answer,language:['en','hi','mr'].includes(result.output_language)?result.output_language:'en'});if(r.audio_base64){const a=new Audio(`data:${r.mime_type};base64,${r.audio_base64}`);await a.play();}setVoiceMessage(r.message||r.status);}catch(e){setVoiceMessage((e as Error).message);}}}>Listen to answer</button>}</>}{saved&&<span role="status">{saved} <Link href="/reports">Reports →</Link></span>}{voiceMessage&&<span role="status">{voiceMessage}</span>}</div><ResultView result={result}/></section>}</>;
}
const FORM_CONFIG:Record<string,{title:string,endpoint:string,kind:string,button:string}>={
 'ask':{title:'Ask a question and inspect the evidence behind the response.',endpoint:'/agents/run',kind:'ask',button:'Ask IP-SAKTI'},
 'patentability':{title:'Screen an invention for evidence gaps and patent-readiness questions.',endpoint:'/patentability/screen',kind:'patent',button:'Run patentability screen'},
 'prior-art':{title:'Search the configured patent provider and inspect detected overlap.',endpoint:'/prior-art/search',kind:'prior_art',button:'Search prior art'},
 'tk-risk':{title:'Check ingredient, therapeutic-use and preparation-process overlap.',endpoint:'/traditional-knowledge/assess',kind:'traditional_knowledge',button:'Assess TK risk'},
 'regulation-compare':{title:'Compare dated source requirements across selected jurisdictions.',endpoint:'/regulations/compare',kind:'comparison',button:'Compare regulations'},
 'document-checker':{title:'Find missing fields using requirements grounded in the loaded sources.',endpoint:'/compliance/check',kind:'compliance',button:'Check document'},
 'compliance-journey':{title:'Build a review checklist from your document and applicable stored requirements.',endpoint:'/compliance/journey',kind:'journey',button:'Build compliance journey'},
};
function ScreenForm({page}:PageProps){const cfg=FORM_CONFIG[page];const[values,setValues]=useState<Record<string,string>>({question:'',title:'',description:'',ingredients:'',process:'',claimed_innovation:'',technical_advantage:'',therapeutic_use:'',language:'en',intent:'',jurisdiction:'IN',product_category:'herbal_product',document_text:'',as_of:'',document_id:''});const[countries,setCountries]=useState(['IN','US','EU','UK']);const[runPrior,setRunPrior]=useState(false);const[result,setResult]=useState<any>(null);const[lastInput,setLastInput]=useState<any>(null);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const[saving,setSaving]=useState(false);const[saved,setSaved]=useState('');const[voiceMessage,setVoiceMessage]=useState('');const set=(key:string,value:string)=>setValues(v=>({...v,[key]:value}));
 useEffect(()=>{const savedLanguage=localStorage.getItem('ip-sakti-language')||'en';set('language',savedLanguage);if(page==='ask')set('question',new URLSearchParams(window.location.search).get('question')||'');},[page]);
 const invention=['patentability','prior-art','tk-risk'].includes(page);const compliance=['document-checker','compliance-journey'].includes(page);
 const makeInput=()=>{if(page==='ask')return{question:values.question,language:values.language,...(values.intent?{intent:values.intent}:{})};if(page==='regulation-compare')return{jurisdictions:countries,product_category:values.product_category,...(values.as_of?{as_of:values.as_of}:{})};if(compliance)return{jurisdiction:values.jurisdiction,product_category:values.product_category,document_text:values.document_text,...(values.document_id?{document_id:values.document_id}:{}),...(values.as_of?{as_of:values.as_of}:{})};const common={title:values.title,description:values.description,ingredients:values.ingredients.split(',').map(s=>s.trim()).filter(Boolean),process:values.process};if(page==='tk-risk')return{...common,therapeutic_use:values.therapeutic_use};return{...common,claimed_innovation:values.claimed_innovation,technical_advantage:values.technical_advantage,...(page==='patentability'?{run_prior_art_search:runPrior}:{limit:10})};};
 const field=(key:string,label:string,placeholder='',required=false,multiline=false)=><label key={key} className="form-field"><span>{label}{required&&<b className="required"> *</b>}</span>{multiline?<textarea rows={key==='document_text'?9:4} value={values[key]} placeholder={placeholder} required={required} onChange={e=>set(key,e.target.value)}/>:<input value={values[key]} placeholder={placeholder} required={required} onChange={e=>set(key,e.target.value)}/>}</label>;
 return <><PageHeader page={page} description={cfg.title}/><div className="workspace-columns"><section className="panel form-panel"><div className="section-title"><h2>{page==='ask'?'Research question':compliance?'Document details':'Screening inputs'}</h2><span className="step-label">01 / INPUT</span></div><form onSubmit={async e=>{e.preventDefault();if(busy)return;setError('');setSaved('');setBusy(true);setResult(null);const input=makeInput();try{const r=await api(cfg.endpoint,input);setResult(r);setLastInput(input);}catch(err){setError((err as Error).message);}finally{setBusy(false);}}}>
 {page==='ask'&&<><ChatBox value={values.question} onChange={v=>set('question',v)} language={values.language}/><div className="form-row"><label className="form-field"><span>Response language</span><select value={values.language} onChange={e=>set('language',e.target.value)}><option value="en">English</option><option value="hi">हिन्दी</option><option value="mr">मराठी</option></select></label><label className="form-field"><span>Route</span><select value={values.intent} onChange={e=>set('intent',e.target.value)}><option value="">Detect intent</option><option value="ask">Grounded question answering</option><option value="patent">Patent agent</option><option value="prior_art">Prior-art agent</option><option value="traditional_knowledge">Traditional knowledge agent</option><option value="international">International regulation agent</option><option value="ayush">AYUSH agent</option><option value="compliance">Compliance agent</option></select></label></div></>}
 {invention&&<>{field('title','Invention or product title','Name your invention',page!=='tk-risk')}{field('description','Description','Describe the formulation, use and technical details.',true,true)}{field('ingredients','Ingredients','Separate ingredient names with commas')}{field('process','Preparation process','Describe the actual preparation steps',false,true)}{page==='tk-risk'?field('therapeutic_use','Claimed therapeutic use','Describe the claimed use; this does not verify efficacy.'): <>{field('claimed_innovation','Claimed innovation','What change are you proposing?',false,true)}{field('technical_advantage','Technical advantage','Describe measurements or available evidence.',false,true)}</>}{page==='patentability'&&<label className="checkbox-label"><input type="checkbox" checked={runPrior} onChange={e=>setRunPrior(e.target.checked)}/>Include configured prior-art search</label>}</>}
 {page==='regulation-compare'&&<fieldset><legend>Jurisdictions</legend><div className="country-options">{[['IN','India'],['US','USA'],['EU','European Union'],['UK','United Kingdom']].map(([code,label])=><label className={countries.includes(code)?'selected':''} key={code}><input type="checkbox" checked={countries.includes(code)} onChange={e=>setCountries(c=>e.target.checked?[...c,code]:c.filter(v=>v!==code))}/><span><strong>{code}</strong>{label}</span></label>)}</div></fieldset>}
 {(page==='regulation-compare'||compliance)&&<>{compliance&&<label className="form-field"><span>Jurisdiction</span><select value={values.jurisdiction} onChange={e=>set('jurisdiction',e.target.value)}>{[['IN','India'],['US','USA'],['EU','European Union'],['UK','United Kingdom']].map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label>}{field('product_category','Product category','Must match the configured source corpus',true)}<label className="form-field"><span>Assessment date</span><input type="date" value={values.as_of} onChange={e=>set('as_of',e.target.value)}/><small>Leave blank for today. Only stored versions applicable on this date are selected.</small></label></>}
 {compliance&&<>{field('document_text','Document text','Paste explicit fields, one per line:\nProduct name: …\nIngredients: …\nManufacturer: …',false,true)}<p className="fine-print">Use labels matching the source requirements. Fields remain unverified user assertions.</p>{field('document_id','Stored document ID (optional)','Copy an ID from Knowledge Library')}<Link href="/knowledge-library">Upload or inspect a document ↗</Link></>}
 <div className="form-actions"><button className="button primary" disabled={busy||(page==='regulation-compare'&&!countries.length)} type="submit">{busy?<><span className="spinner"/>Processing…</>:cfg.button}</button><small>Review source scope and limitations before relying on a result.</small></div></form>{error&&<ErrorBox error={error}/>}</section>
 <aside className="context-panel"><span className="step-label">02 / EVIDENCE</span><h3>Every conclusion needs a source.</h3><p>{page==='prior-art'?'A real search requires a configured patent provider. An empty or limited search cannot establish novelty.':page==='tk-risk'?'TK assessment uses only the configured corpus. No TKDL access or final clearance is bundled.':'The workspace keeps source excerpts, uncertainty and review gaps alongside your screening.'}</p><div className="context-rule"><strong>Screening quality</strong><p>Scores describe completeness, overlap or grounding. They do not measure legal correctness.</p></div><Link href="/knowledge-library">Inspect your source library ↗</Link></aside></div>
 {busy?<Loading/>:<section className="panel result-panel"><div className="result-actions">{result&&<><button className="button secondary small" disabled={saving} onClick={async()=>{setSaving(true);setSaved('');try{await api('/reports',{title:`${navigation.find(n=>n[0]===page)?.[1]} report`,kind:cfg.kind,...(result.assessment_id?{assessment_id:result.assessment_id}:{input:lastInput})});setSaved('Report saved. Open Reports to export it.');}catch(e){setSaved((e as Error).message);}finally{setSaving(false);}}}>{saving?'Saving report…':'Save assessment report'}</button>{page==='ask'&&<button className="button ghost small" onClick={async()=>{try{const r=await api('/voice/synthesize',{text:result.answer,language:['en','hi','mr'].includes(result.output_language)?result.output_language:'en'});if(r.audio_base64){const a=new Audio(`data:${r.mime_type};base64,${r.audio_base64}`);await a.play();}setVoiceMessage(r.message||r.status);}catch(e){setVoiceMessage((e as Error).message);}}}>Listen to answer</button>}</>}{saved&&<span role="status">{saved} <Link href="/reports">Reports ↗</Link></span>}{voiceMessage&&<span role="status">{voiceMessage}</span>}</div><ResultView result={result}/></section>}</>;
}
function Library(){
 const{data,error,busy,reload}=useResource('/documents');const[selected,setSelected]=useState<any>(null);const[message,setMessage]=useState('');const[indexing,setIndexing]=useState('');
 const inspect=async(id:string)=>{setMessage('');try{setSelected(await api(`/documents/${id}`));}catch(e){setMessage((e as Error).message);}};
 const indexDocument=async(d:any)=>{setIndexing(d.id);setMessage('');try{const r=await api(`/documents/${d.id}/ingest`,{});setMessage(`${String(r.status).replaceAll('_',' ')}: ${r.stored_chunks} chunks stored.`);reload();}catch(e){setMessage((e as Error).message);}finally{setIndexing('');}};
 return <><PageHeader page="knowledge-library" description="Review source files, verification state and knowledge-base indexing without exposing extracted pages in the main list."/>
  {message&&<Notice>{message}</Notice>}
  <div className="library-layout"><section className="panel library-panel"><div className="section-title"><div><span className="eyebrow">SOURCE LIBRARY</span><h2>Documents</h2></div><button className="button ghost small" onClick={reload}>Refresh</button></div>
   {busy?<Loading/>:error?<UnavailableState title="Library index is temporarily unavailable" error={error} retry={reload}>You can still choose a source document after the local backend is available again.</UnavailableState>:!data.documents.length?<Empty title="Your library is empty">Add source documents to inspect their content or screen explicit document fields.</Empty>:<div className="document-list">{data.documents.map((d:any)=><article className="document-card" key={d.id}><span className="file-icon">{d.extension.slice(1).toUpperCase()}</span><div className="document-card__body"><div className="document-card__title"><strong>{d.name}</strong><span className={`badge${d.status==='no_extractable_text'?' warning':''}`}>{d.status==='no_extractable_text'?'No extractable text':'Stored'}</span></div><div className="document-facts"><span>{d.page_count?`${d.page_count} pages`:'Text document'}</span><span>{formatFileSize(d.size_bytes)}</span><span>{d.source_verified?'Source verified':'Source unverified'}</span><span className={d.rag_indexed?'positive':'muted'}>{d.rag_indexed?'Indexed for RAG':'Not indexed'}</span></div><div className="inline-actions"><button className="button secondary small" onClick={()=>inspect(d.id)}>Inspect</button>{d.extension==='.pdf'&&<button className="button ghost small" disabled={!!indexing} onClick={()=>indexDocument(d)}>{indexing===d.id?'Indexing…':d.rag_indexed?'Reindex':'Index for RAG'}</button>}<button className="button ghost small" onClick={()=>download(`/documents/${d.id}/file`,d.name).catch(e=>setMessage(e.message))}>Download</button></div></div></article>)}</div>}
  </section><DocumentUploader onUploaded={r=>{setSelected(r);reload();}}/></div>
  {selected&&<><button type="button" className="detail-scrim" aria-label="Close document details" onClick={()=>setSelected(null)}/><aside className="document-drawer" role="dialog" aria-modal="true" aria-labelledby="document-detail-title"><div className="document-drawer__header"><div><span className="eyebrow">DOCUMENT INSPECTOR</span><h2 id="document-detail-title">{selected.name}</h2></div><button className="panel-close" type="button" aria-label="Close document details" onClick={()=>setSelected(null)}>✕</button></div><div className="document-drawer__body"><div className="document-facts prominent"><span>{selected.extension?.slice(1).toUpperCase()}</span><span>{selected.page_count?`${selected.page_count} pages`:'Text document'}</span><span>{formatFileSize(selected.size_bytes)}</span><span>{selected.rag_indexed?'Indexed for RAG':'Not indexed'}</span></div><Notice>Stored content is not automatically verified or authoritative. Scanned PDFs may require OCR outside this application.</Notice><div className="document-pages">{selected.pages?.map((p:any,i:number)=><article className="document-page" key={p.page||i}><span className="eyebrow">{p.page?`PAGE ${p.page}`:'DOCUMENT TEXT'}</span><pre>{p.text||'No extractable text on this page.'}</pre></article>)}</div><details className="raw-detail compact"><summary>Technical details</summary><dl className="technical-list"><div><dt>Document ID</dt><dd><code>{selected.id}</code></dd></div><div><dt>SHA-256</dt><dd><code>{selected.sha256}</code></dd></div><div><dt>Stored</dt><dd>{formatLocalTime(selected.created_at)}</dd></div></dl></details></div></aside></>}
 </>;
}
function Changes(){const{data,error,busy,reload}=useResource('/regulations/changes');const[syncing,setSyncing]=useState(false);const[message,setMessage]=useState('');return <><PageHeader page="regulation-changes" description="Inspect differences between stored source versions and the fields they affect." action={<button className="button primary" disabled={syncing} onClick={async()=>{setSyncing(true);try{const r=await api('/regulations/sync',{});setMessage(`${r.status.replaceAll('_',' ')} · ${r.imported||0} versions imported`);reload();}catch(e){setMessage((e as Error).message);}finally{setSyncing(false);}}}>{syncing?'Synchronizing…':'Synchronize configured source'}</button>}/>{message&&<Notice>{message}</Notice>}{busy?<Loading/>:error?<ErrorBox error={error} retry={reload}/>:<><Notice>{describeMode(data.mode)} · Last successful synchronization: {data.sync?.last_success?new Date(data.sync.last_success).toLocaleString():'None'}. Monitoring is manual; no continuous live feed is implied.</Notice>{!data.changes.length?<section className="panel"><Empty title="No stored changes to compare">Configure a versioned regulatory corpus and synchronize it. No changes here does not mean regulations have not changed.</Empty></section>:data.changes.map((c:any,i:number)=><section className="panel change-card" key={i}><div className="row-between"><span className="eyebrow">{c.jurisdiction} · {c.regulation_id}</span><span className={`badge ${c.mode==='mock'?'warning':''}`}>{describeMode(c.mode)}</span></div><h2>{c.from_version} <span className="muted">→</span> {c.to_version}</h2><p>Stored effective date: {c.effective_from}</p><div className="change-stats"><span><strong>{c.added.length}</strong> Added requirements</span><span><strong>{c.changed.length}</strong> Changed requirements</span><span><strong>{c.removed.length}</strong> Removed requirements</span></div><h3>Fields to review</h3><div className="chips">{c.impact.affected_fields.map((f:string)=><span className="chip" key={f}>{f.replaceAll('_',' ')}</span>)}</div><ul className="checklist">{c.impact.actions.map((a:string)=><li key={a}>{a}</li>)}</ul><details><summary>Source text diff</summary><pre>{c.text_diff||'No source text change.'}</pre></details><details><summary>Requirement and provenance detail</summary><pre>{JSON.stringify(c,null,2)}</pre></details></section>)}</>}</>;}
function Alerts(){const{data,error,busy,reload}=useResource('/alerts');const[message,setMessage]=useState('');return <><PageHeader page="regulatory-alerts" description="Review in-app alerts derived from the regulation versions you synchronized."/>{message&&<Notice>{message}</Notice>}{busy?<Loading/>:error?<ErrorBox error={error} retry={reload}/>:<section className="panel">{!data.alerts.length?<Empty title="No stored alerts">Alerts appear when synchronized snapshots contain changes. No external messages are sent.</Empty>:data.alerts.map((a:any)=><article className="alert-item" key={a.id}><div><span className={`badge ${a.mode==='mock'?'warning':''}`}>{describeMode(a.mode)}</span><h3>{a.title}</h3><p>{a.jurisdiction} · Effective date in source: {a.effective_from} · Review priority: {a.impact.review_priority}</p><small>{a.impact.affected_fields.join(' · ')}</small></div><button className="button secondary small" disabled={a.acknowledged} onClick={async()=>{try{await api(`/alerts/${a.id}/acknowledge`,{});reload();}catch(e){setMessage((e as Error).message);}}}>{a.acknowledged?'Acknowledged':'Mark reviewed'}</button></article>)}</section>}</>;}
function UnavailableState({title,error,retry,children}:{title:string,error:string,retry:()=>void,children?:React.ReactNode}){return <section className="unavailable-state" role="status"><div><span className="eyebrow">LOCAL SERVICE UNAVAILABLE</span><h2>{title}</h2><p>{children||'The workspace can be refreshed when the local service is available again.'}</p><small>{error}</small></div><div className="inline-actions"><button className="button secondary small" onClick={retry}>Retry</button><Link className="button ghost small" href="/settings">Check settings</Link></div></section>;}
function displayMetric(value:any,fallback='—'){if(typeof value==='number')return Number.isInteger(value)?String(value):value.toFixed(2);return value===undefined||value===null||value===''?fallback:String(value);}
function Reports(){const{data,error,busy,reload}=useResource('/reports');const[selected,setSelected]=useState<any>(null);const[details,setDetails]=useState<Record<string,any>>({});const[message,setMessage]=useState('');useEffect(()=>{let active=true;const reports=data?.reports;if(!reports?.length){setDetails({});return()=>{active=false;};}Promise.all(reports.map((r:any)=>api(`/reports/${r.id}`).then(detail=>[r.id,detail] as const).catch(()=>[r.id,null] as const))).then(entries=>{if(active)setDetails(Object.fromEntries(entries.filter(([,detail])=>detail)));});return()=>{active=false;};},[data]);return <><PageHeader page="reports" description="Saved assessments retain the original evidence, source mode and limitations."/>{message&&<Notice>{message}</Notice>}{busy?<Loading/>:error?<UnavailableState title="Reports are temporarily unavailable" error={error} retry={reload}>Saved reports are not lost. Start or reconnect the local backend, then refresh this list.</UnavailableState>:<section className="panel report-panel">{!data.reports.length?<Empty title="No saved reports yet">Run a screening and select Save assessment report.</Empty>:<div className="table-scroll"><table className="report-table"><thead><tr><th>Report</th><th>Task</th><th>Evidence / source mode</th><th>Created locally</th><th>Status</th><th>Trust</th><th>Evidence</th><th>Sources</th><th>Actions</th></tr></thead><tbody>{data.reports.map((r:any)=>{const detail=details[r.id]||r;const metrics=reportMetrics(detail);const sourceMode=r.source_mode||r.mode;return <tr key={r.id}><th>{r.title}<small>Saved assessment</small></th><td>{r.task||String(r.kind||'assessment').replaceAll('_',' ')}</td><td><span className={`badge ${sourceMode==='synthetic'||r.mode==='mock'?'warning':''}`}>{describeMode(sourceMode)}</span></td><td>{formatLocalTime(r.created_at)}</td><td>{metrics.status}</td><td>{displayMetric(metrics.trust)}</td><td>{displayMetric(metrics.evidence)}</td><td>{displayMetric(metrics.sources,'0')}</td><td><button className="button secondary small" onClick={async()=>{try{setSelected(await api(`/reports/${r.id}`));}catch(e){setMessage((e as Error).message);}}}>Open report</button></td></tr>;})}</tbody></table></div>}</section>}{selected&&<section className="panel result-panel"><div className="section-title"><h2>{selected.title}</h2><button className="button ghost small" onClick={()=>setSelected(null)}>Close</button></div><div className="inline-actions">{[['json','JSON','json'],['markdown','Markdown','md'],['html','Printable HTML','html']].map(([format,label,suffix])=><button className="button secondary small" key={format} onClick={()=>download(`/reports/${selected.id}/export?format=${format}`,`IP-SAKTI-report.${suffix}`).catch(e=>setMessage(e.message))}>Export {label} ↓</button>)}</div><p className="fine-print">HTML exports can be printed to PDF from your browser. Each export includes all citations and limitations.</p><ResultView result={selected.assessment}/></section>}</>;}
function SettingStatus({label,value,detail,status}:{label:string,value?:any,detail:string,status?:string}){const resolved=status||statusLabel(value);const tone=resolved==='Ready'?'ready':resolved==='Unavailable'?'unavailable':'attention';return <div className="settings-status"><div><strong>{label}</strong><small>{detail}</small></div><span className={`service-state ${tone}`}><i/>{resolved}</span></div>;}
function Settings(){const{data,error,busy,reload}=useResource('/status');const[token,setToken]=useState('');const[language,setLanguage]=useState('en');const[message,setMessage]=useState('');useEffect(()=>{setToken(sessionStorage.getItem('ip-sakti-api-token')||'');setLanguage(localStorage.getItem('ip-sakti-language')||'en');},[]);const providers=data?.providers||{};const providerStatus=data?.provider_status||{};const rag=data?.rag||{};const authKnown=!!data&&!error;const authRequired=data?.authentication_required===true;const tkdlConnected=data?.provider_status?.traditional_knowledge?.tkdl_connected===true;const tokenLabel=!authKnown?'Application API token (checking requirement)':authRequired?'Application API token (required)':'Application API token (not required for this server)';const tokenHelp=!authKnown?'The local server is being checked. Provider API keys always stay in the backend environment.':authRequired?'This server requires its API_AUTH_TOKEN for requests. The token is kept only for this tab session.':'This local server does not require an application token. Provider API keys belong only in the backend environment.';return <><PageHeader page="settings" description="Manage local preferences and inspect truthful local configuration status."/>{message&&<Notice>{message}</Notice>}{error&&<Notice type="error"><strong>Provider status is unavailable.</strong><p>{error}</p><button className="button secondary small" onClick={reload}>Retry status check</button></Notice>}<div className="settings-grid"><section className="panel settings-group"><div className="section-title"><div><span className="eyebrow">READINESS</span><h2>AI &amp; Knowledge</h2></div>{busy&&<small>Checking…</small>}</div><SettingStatus label="Gemini" value={rag.gemini_readiness} detail="Optional model access; readiness requires a working configured pipeline."/><SettingStatus label="RAG workspace" value={rag} detail="Grounded retrieval is ready only when its pipeline and index are usable."/><SettingStatus label="Knowledge library" value={rag.knowledge_base} detail={`${rag.knowledge_base?.indexed_chunks||0} indexed chunks reported by this local workspace.`}/></section><section className="panel settings-group"><div className="section-title"><div><span className="eyebrow">EVIDENCE CONNECTORS</span><h2>Research Sources</h2></div></div><SettingStatus label="Patent / EPO search" value={providers.prior_art} detail="Configured access must complete a successful request before it is verified."/><SettingStatus label="TKDL" status={tkdlConnected?'Ready':'Not connected'} detail={tkdlConnected?'Integration status was reported by the configured service.':'No bundled TKDL connection is available; authorization is assessed separately.'}/><SettingStatus label="Regulation source" value={providers.regulations} detail="Optional; comparisons use only the configured versioned source corpus."/></section><section className="panel settings-group"><div className="section-title"><div><span className="eyebrow">OPTIONAL CAPABILITIES</span><h2>Language &amp; Voice</h2></div></div><SettingStatus label="Translation" value={providerStatus.translation} detail="Local NLLB translation is configured for English, Hindi and Marathi."/><SettingStatus label="Speech to text" value={providerStatus.speech_to_text} detail="Local Whisper speech recognition is configured; typed input also remains available."/><SettingStatus label="Text to speech" value={providerStatus.text_to_speech} detail="Edge TTS is configured for voice playback and requires internet access."/></section><section className="panel settings-group"><div className="section-title"><div><span className="eyebrow">LOCAL ACCESS</span><h2>Security</h2></div></div><SettingStatus label="API authentication" status={!authKnown?'Needs configuration':authRequired&&!token?'Needs configuration':'Ready'} detail={!authKnown?'Waiting for the server to report its authentication state.':authRequired?(token?'API authentication is enabled and this browser session has a token.':'Enter the API token to access protected requests.'):'Disabled for this local development server.'}/><form onSubmit={e=>{e.preventDefault();if(token)sessionStorage.setItem('ip-sakti-api-token',token);else sessionStorage.removeItem('ip-sakti-api-token');localStorage.setItem('ip-sakti-language',language);setMessage('Preferences saved for this browser. API token is retained only for this tab session.');reload();}}><label className="form-field"><span>{tokenLabel}</span><input type="password" autoComplete="off" value={token} onChange={e=>setToken(e.target.value)}/><small>{tokenHelp}</small></label><label className="form-field"><span>Preferred response language</span><select value={language} onChange={e=>setLanguage(e.target.value)}><option value="en">English</option><option value="hi">हिन्दी</option><option value="mr">मराठी</option></select></label><button className="button primary" type="submit">Save preferences</button></form></section></div><details className="panel settings-advanced"><summary>Advanced / Developer configuration</summary><div className="settings-notes"><div><h3>Patent search</h3><p>Select <code>PRIOR_ART_PROVIDER=epo_ops</code> and set EPO OPS credentials in the backend environment. A successful request is required to verify access.</p></div><div><h3>Traditional knowledge &amp; regulation</h3><p>Use an authorized local corpus or a compatible gateway. No TKDL integration is bundled; set TK authorization only after obtaining permission.</p></div><div><h3>Offline demonstration</h3><p>Enable <code>ALLOW_MOCK_DATA=true</code>, <code>TK_PROVIDER=mock</code> and <code>REGULATION_PROVIDER=mock</code> on the backend. Synthetic assessments stay labelled.</p></div><div><h3>Language &amp; voice</h3><p>Translation, speech recognition and synthesis each require separate gateway configuration. Without them, original text and typed input remain available.</p></div></div><p className="fine-print">Backend address: <code>{API_BASE}</code>. See AUTHENTICATION_SETUP.md and .env.example for placeholders and restart the backend after environment changes.</p></details></>;}
function AuroraDashboard(){
 const{data,error,busy,reload}=useResource('/status'); const reports=useResource('/reports'); const[q,setQ]=useState('');
 const providers=Object.entries(data?.providers||{}); const reportItems=reports.data?.reports||[];
 const readyProviders=providers.filter(([,value])=>!['unconfigured','unavailable','disabled'].includes(String(value))).length;
 const ragState=statusLabel(data?.rag); const chunks=data?.rag?.knowledge_base?.indexed_chunks;
 const kpis=[
  ['Knowledge chunks', busy?'Checking…':typeof chunks==='number'?String(chunks):'Unavailable', 'Indexed evidence reported by this workspace.'],
  ['Connected providers', busy?'Checking…':providers.length?`${readyProviders} / ${providers.length}`:'Unavailable', 'Only reported provider states are counted.'],
  ['Saved reports', reports.busy?'Checking…':String(reportItems.length), 'Assessment snapshots retained locally.'],
  ['RAG readiness', busy?'Checking…':ragState, 'Readiness is reported by the local service.'],
 ];
 const actions=[['ask','Ask IP-SAKTI','Pose an evidence-grounded AYUSH question.'],['patentability','Patentability','Screen novelty, inventive step and gaps.'],['prior-art','Prior Art','Review configured patent records and overlap.'],['tk-risk','TK Risk','Make authorization and corpus scope visible.'],['regulation-compare','Regulation Compare','Compare only source-bound requirements.']];
 const statusRows=[['Gemini',data?.rag?.gemini_readiness],['RAG',data?.rag],['EPO / Prior Art',data?.providers?.prior_art],['Traditional Knowledge',data?.providers?.traditional_knowledge],['TKDL',data?.provider_status?.traditional_knowledge?.tkdl_connected===true?'Ready':'Not connected'],['Regulation',data?.providers?.regulations],['Translation',data?.provider_status?.translation],['STT',data?.provider_status?.speech_to_text],['TTS',data?.provider_status?.text_to_speech],['API authentication',data?.authentication_required===true?'Ready':'Not required']];
 const dashboardError=Array.from(new Set([error,reports.error].filter(Boolean))).join(' · ');
 return <>
  <section className="aurora-hero" aria-labelledby="aurora-title">
   <div className="aurora-orb orb-one"/><div className="aurora-orb orb-two"/><div className="aurora-leaf" aria-hidden="true"><i/><i/><i/></div>
   <div className="aurora-hero__copy"><span className="eyebrow">AYUSH / IP INTELLIGENCE WORKSPACE</span><h1 id="aurora-title">IP-SAKTI <em>Intelligence</em></h1><p>Evidence-grounded IP &amp; Regulatory Intelligence for AYUSH Innovation</p><div className="aurora-chips"><span>Traceable evidence</span><span>Safe screening</span><span>Source-aware research</span></div><strong>From Traditional Knowledge to Global Impact</strong></div>
   <form className="aurora-search" onSubmit={event=>{event.preventDefault();if(q.trim())window.location.href=`/ask?question=${encodeURIComponent(q.trim())}`;}}><label htmlFor="aurora-question">Begin an investigation</label><div><input id="aurora-question" value={q} onChange={event=>setQ(event.target.value)} placeholder="Ask about a formulation, claim or market…" required/><button className="button primary" type="submit">Investigate <b>↗</b></button></div><small>Results preserve source scope, limitations and evidence gaps.</small></form>
  </section>
  {dashboardError&&<ErrorBox error={dashboardError} retry={error?reload:reports.reload}/>}
  <section className="aurora-kpis" aria-label="Workspace intelligence summary">{kpis.map(([label,value,detail],index)=><article className="aurora-kpi" key={label}><span>0{index+1}</span><strong>{value}</strong><h2>{label}</h2><p>{detail}</p></article>)}</section>
  <section className="aurora-section"><div className="section-title"><div><span className="eyebrow">INTELLIGENCE SURFACES</span><h2>Start from the question that matters.</h2></div><p>Every route keeps claims tied to the evidence that supports them.</p></div><div className="aurora-actions">{actions.map(([href,title,description],index)=><Link href={`/${href}`} key={href} className="aurora-action"><span>0{index+1}</span><div><h3>{title}</h3><p>{description}</p></div><b>↗</b></Link>)}</div></section>
  <div className="aurora-columns"><section className="panel aurora-readiness"><div className="section-title"><div><span className="eyebrow">SYSTEM READINESS</span><h2>What is actually available</h2></div><Link href="/settings">Inspect settings ↗</Link></div>{busy?<Loading/>:<div className="aurora-statuses">{statusRows.map(([label,value])=>{const disconnected=label==='TKDL'&&value==='Not connected';const labelValue=disconnected?'Not connected':statusLabel(value);return <div key={label}><span>{label}</span><b className={`service-state ${disconnected?'attention':statusTone(value)}`}><i/>{labelValue}</b></div>;})}</div>}<p className="fine-print">Provider state is not search evidence, clearance or a legal conclusion.</p></section><section className="panel aurora-recent"><div className="section-title"><div><span className="eyebrow">ACTIVITY</span><h2>Recent reports</h2></div><Link href="/reports">All reports ↗</Link></div>{reports.busy?<Loading/>:reportItems.length?<div className="aurora-report-list">{reportItems.slice(0,4).map((report:any)=><Link href="/reports" key={report.id}><span>{report.task||report.kind||'Assessment'}</span><strong>{report.title}</strong><small>{formatLocalTime(report.created_at)} · {describeMode(report.source_mode||report.mode)}</small><b>Open ↗</b></Link>)}</div>:<Empty title="No reports yet">Saved assessments will appear here with their original evidence and source mode.</Empty>}</section></div>
  <section className="panel aurora-journey"><div className="section-title"><div><span className="eyebrow">INNOVATION JOURNEY</span><h2>Move deliberately from insight to review.</h2></div></div><ol>{[['01','Frame','Define the formulation, intent and jurisdiction.'],['02','Investigate','Search only configured sources and record limitations.'],['03','Review','Assess overlap, evidence quality and unanswered gaps.'],['04','Export','Retain a traceable snapshot for expert review.']].map(([number,title,copy])=><li key={number}><span>{number}</span><div><strong>{title}</strong><p>{copy}</p></div></li>)}</ol></section>
 </>;
}
export default function WorkspacePage({page}:PageProps){if(page==='dashboard')return <AuroraDashboard/>;if(FORM_CONFIG[page])return <RefinedScreenForm key={page} page={page}/>;if(page==='knowledge-library')return <Library/>;if(page==='regulation-changes')return <Changes/>;if(page==='regulatory-alerts')return <Alerts/>;if(page==='reports')return <Reports/>;return <Settings/>;}
